	/**
	 * Default Constructor
	 */
    public ExperimentService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ExperimentEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ExperimentRepository.class) );
		this.validator		= applicationContext.getBean(ExperimentValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Experiment
	 */
		public Experiment createExperiment( CreateExperimentCommand command ) {

		Experiment entity = new Experiment();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setExperimentId( command.getExperimentId() );
            entity.setName( command.getName() );
            entity.setObjective( command.getObjective() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Experiment {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateExperimentCommand
	 * @return		Experiment
	 */
	public Experiment updateExperiment( UpdateExperimentCommand command ) {

		Experiment entity = new Experiment();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setExperimentId( command.getExperimentId() );
            entity.setName( command.getName() );
            entity.setObjective( command.getObjective() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setTrainingRuns( command.getTrainingRuns() );
            entity.setModels( command.getModels() );
            entity.setNotebooks( command.getNotebooks() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Experiment {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteExperimentCommand
	 */
	public void delete( DeleteExperimentCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getExperimentId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Experiment {0} ", id );

	}

	/**
	 * Method to retrieve the Experiment via ExperimentFetchOneSummary
	 * @param 	summary ExperimentFetchOneSummary
	 * @return 	ExperimentFetchOneResponse
	 */
	public Experiment getExperiment( ExperimentFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ExperimentFetchOneSummary arg cannot be null" );

		Experiment entity = null;
		UUID id = summary.getExperimentId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Experiment using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Experiments
	 *
	 * @return 	List<Experiment>
	 */
    public List<Experiment> getAllExperiment() {
		List<Experiment> list = projector.findAll( new FindAllExperimentQuery() );
		return list;
	}

	/**
	 * assign Workspace on Experiment
	 * @param		command AssignWorkspaceToExperimentCommand
	 */
	public void assignWorkspace( AssignWorkspaceToExperimentCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignWorkspace(command.getExperimentId(), command.getAssignment());

	}

	/**
	 * unAssign Workspace on Experiment
	 * @param		command UnAssignWorkspaceFromExperimentCommand
	 */
	public void unAssignWorkspace( UnAssignWorkspaceFromExperimentCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignWorkspace(command.getExperimentId());
	}
	

